package org.clafer.frontend;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import org.clafer.frontend.Syntax.*;

/**
 * Parses a model in the full Clafer language into its {@link Syntax} tree, as
 * the compiler parses it ({@code clafer.cf}, generated by BNFC and Happy, and
 * {@code Language.Clafer.parse}).
 * <p>
 * It is a recursive descent over the grammar, one method per level of
 * expression, which takes the choices that Happy takes:
 * <ul>
 * <li>an expression goes on as long as it can, so that in {@code [a -b]} the
 * {@code -} is a subtraction, and {@code a not} must go on with {@code in};
 * a list of expressions has no separator;</li>
 * <li>a quantifier starts a declaration, {@code some x; y : X | e}, when
 * {@code disj}, or a name and {@code ;} or {@code :}, follow it;</li>
 * <li>a cardinality is taken whenever one can start, e.g., the {@code 2..3}
 * of {@code a 2..3 b} is the card of {@code a};</li>
 * <li>a clafer must start on a new line, after its previous sibling
 * clafer.</li>
 * </ul>
 * The layout is resolved first ({@link Layout}), so the parser reads blocks
 * as braces, and lines of siblings with a separator between them.
 * <p>
 * The parser does not stop at an error: it reports it, skips to the next line
 * at the same or a lower indentation, and goes on, so that a model with
 * errors on several lines reports all of them, and the tree has the rest.
 */
public final class ClaferParser {

    /**
     * The tree of a model and its errors.
     *
     * @param model the tree; where there are errors, what was read around
     * them
     * @param comments the comments and escapes, in order
     * @param diagnostics the errors of the lexer, the layout and the parser,
     * in order
     */
    public record Result(Model model, List<Token> comments, List<Diagnostic> diagnostics) {
    }

    private static final class ParseError extends RuntimeException {

        private static final long serialVersionUID = 1L;
        private final transient Diagnostic diagnostic;

        ParseError(Diagnostic diagnostic) {
            super(diagnostic.toString(), null, false, false);
            this.diagnostic = diagnostic;
        }
    }

    private static final Map<String, BinaryOp> Comparisons = Map.of(
            "<", BinaryOp.Lt, ">", BinaryOp.Gt, "=", BinaryOp.Eq, "<=", BinaryOp.Lte, ">=", BinaryOp.Gte,
            "!=", BinaryOp.Neq, "in", BinaryOp.In);
    private static final Map<String, UnaryOp> TemporalPrefix = Map.of(
            "F", UnaryOp.LtlF, "eventually", UnaryOp.Eventually, "G", UnaryOp.LtlG, "globally", UnaryOp.Globally,
            "X", UnaryOp.LtlX, "next", UnaryOp.Next, "previous", UnaryOp.Previous, "once", UnaryOp.Once,
            "historically", UnaryOp.Historically);
    private static final Map<String, Quant> Quants = Map.of(
            "no", Quant.No, "not", Quant.Not, "lone", Quant.Lone, "one", Quant.One, "some", Quant.Some);
    private static final Map<String, PatternKind> PrefixPatterns = Map.of(
            "never", PatternKind.Never, "sometime", PatternKind.Sometime, "lonce", PatternKind.LessOrOnce,
            "always", PatternKind.Always);
    private static final Map<String, TempModifierKind> Modifiers = Map.of(
            "initial", TempModifierKind.Initial, "final", TempModifierKind.Final,
            "finalref", TempModifierKind.FinalRef, "finaltarget", TempModifierKind.FinalTarget);
    private static final Set<String> GroupKeywords = Set.of("xor", "or", "mux", "opt");
    /**
     * The words that start an expression.
     */
    private static final Set<String> ExpStartWords = Set.of(
            "all", "if", "let", "never", "sometime", "lonce", "always", "initially", "finally",
            "F", "eventually", "G", "globally", "X", "next", "previous", "once", "historically",
            "max", "min", "sum", "product", "no", "not", "lone", "one", "some");

    private final List<Token> tokens;
    private int pos = 0;
    private final List<Diagnostic> diagnostics = new ArrayList<>();

    private ClaferParser(List<Token> tokens) {
        this.tokens = tokens;
    }

    /**
     * Parses a model.
     *
     * @param source the text of the model
     * @return its tree, comments and errors
     */
    public static Result parse(String source) {
        ClaferLexer.Result lexed = ClaferLexer.lex(source);
        Layout.Result laid = Layout.resolve(lexed);
        ClaferParser parser = new ClaferParser(laid.tokens());
        parser.diagnostics.addAll(lexed.diagnostics());
        parser.diagnostics.addAll(laid.diagnostics());
        Model model = parser.model();
        sameLineClafers(model.declarations().stream()
                .filter(d -> d instanceof Element).map(d -> (Element) d).toList(), parser.diagnostics);
        List<Diagnostic> sorted = new ArrayList<>(parser.diagnostics);
        sorted.sort((a, b) -> a.span().line() != b.span().line()
                ? Integer.compare(a.span().line(), b.span().line())
                : Integer.compare(a.span().column(), b.span().column()));
        return new Result(model, lexed.others(), Collections.unmodifiableList(sorted));
    }

    // ------------------------------------------------------------------
    // Tokens
    // ------------------------------------------------------------------
    private Token peek() {
        return tokens.get(pos);
    }

    private Token peek(int offset) {
        return tokens.get(Math.min(pos + offset, tokens.size() - 1));
    }

    private Token take() {
        Token t = tokens.get(pos);
        if (t.kind() != TokenKind.EOF) {
            pos++;
        }
        return t;
    }

    /**
     * @return whether the token is the symbol or reserved word
     */
    private static boolean is(Token t, String text) {
        return (t.kind() == TokenKind.SYMBOL || t.kind() == TokenKind.KEYWORD) && t.text().equals(text);
    }

    private boolean at(String text) {
        return is(peek(), text);
    }

    private boolean accept(String text) {
        if (at(text)) {
            pos++;
            return true;
        }
        return false;
    }

    private Token expect(String text) {
        if (!at(text)) {
            throw error(peek(), "Expected '" + text + "' but found " + show(peek()));
        }
        return take();
    }

    private static boolean isOpen(Token t) {
        return t.kind() == TokenKind.INDENT || is(t, "{");
    }

    private static boolean isClose(Token t) {
        return t.kind() == TokenKind.DEDENT || is(t, "}");
    }

    /**
     * @return the last token read that is in the source, not one the layout
     * inserted
     */
    private Token last() {
        for (int i = pos - 1; i > 0; i--) {
            TokenKind kind = tokens.get(i).kind();
            if (kind != TokenKind.INDENT && kind != TokenKind.DEDENT && kind != TokenKind.SEPARATOR) {
                return tokens.get(i);
            }
        }
        return tokens.get(0);
    }

    private SourceSpan from(Token start) {
        Token end = last();
        if (pos == 0 || end.span().line() < start.span().line()
                || (end.span().line() == start.span().line() && end.span().endColumn() < start.span().column())) {
            return SourceSpan.at(start.span().line(), start.span().column());
        }
        return new SourceSpan(start.span().line(), start.span().column(), end.span().endLine(), end.span().endColumn());
    }

    private static SourceSpan join(Node a, Node b) {
        return new SourceSpan(a.span().line(), a.span().column(), b.span().endLine(), b.span().endColumn());
    }

    /**
     * An error at a token; at the end of the model, after the last token, an
     * inserted one included, as the compiler puts it.
     */
    private ParseError error(Token at, String message) {
        if (at.kind() == TokenKind.EOF && tokens.size() > 1) {
            Token lastToken = tokens.get(tokens.size() - 2);
            return new ParseError(new Diagnostic(SourceSpan.at(lastToken.span().line(),
                    lastToken.span().column() + lastToken.text().length()), message));
        }
        return new ParseError(new Diagnostic(SourceSpan.at(at.span().line(), at.span().column()), message));
    }

    private static String show(Token t) {
        return switch (t.kind()) {
            case EOF -> "the end of the model";
            case INDENT -> "an indented line";
            case DEDENT -> "the end of an indented block";
            case SEPARATOR -> "a new line";
            case KEYWORD -> "the reserved word '" + t.text() + "'";
            default -> "'" + t.text() + "'";
        };
    }

    private Ident ident(String what) {
        Token t = peek();
        if (t.kind() != TokenKind.WORD) {
            throw error(t, "Expected " + what + " but found " + show(t));
        }
        pos++;
        return new Ident(t.span(), t.text());
    }

    // ------------------------------------------------------------------
    // Declarations and elements
    // ------------------------------------------------------------------
    private Model model() {
        Token start = peek();
        List<Declaration> declarations = new ArrayList<>();
        while (peek().kind() != TokenKind.EOF) {
            if (peek().kind() == TokenKind.SEPARATOR) {
                pos++;
                continue;
            }
            int before = pos;
            try {
                if (at("enum")) {
                    declarations.add(enumDecl());
                } else if (startsElement(peek())) {
                    declarations.add(element());
                } else {
                    throw error(peek(), "Expected a clafer, a constraint, an objective, an assertion or an enumeration"
                            + " but found " + show(peek()));
                }
            } catch (ParseError e) {
                recover(e, before);
            }
        }
        SourceSpan span = declarations.isEmpty() ? SourceSpan.at(start.span().line(), start.span().column())
                : join(declarations.get(0), declarations.get(declarations.size() - 1));
        return new Model(span, declarations);
    }

    /**
     * Reports an error and skips to the next line at the same or a lower
     * indentation: to the next separator, or to the end of the block, outside
     * the blocks opened since the error.
     */
    private void recover(ParseError e, int before) {
        diagnostics.add(e.diagnostic);
        if (pos == before && peek().kind() != TokenKind.EOF) {
            Token t = take();
            if (isOpen(t)) {
                skipBlock();
            }
        }
        int depth = 0;
        while (peek().kind() != TokenKind.EOF) {
            Token t = peek();
            if (depth == 0 && (t.kind() == TokenKind.SEPARATOR || isClose(t))) {
                return;
            }
            if (isOpen(t)) {
                depth++;
            } else if (isClose(t)) {
                depth--;
            }
            pos++;
        }
    }

    private void skipBlock() {
        int depth = 1;
        while (depth > 0 && peek().kind() != TokenKind.EOF) {
            Token t = take();
            if (isOpen(t)) {
                depth++;
            } else if (isClose(t)) {
                depth--;
            }
        }
    }

    private EnumDecl enumDecl() {
        Token start = expect("enum");
        Ident name = ident("the name of the enumeration");
        expect("=");
        List<Ident> literals = new ArrayList<>();
        literals.add(ident("a literal"));
        while (accept("|")) {
            literals.add(ident("a literal"));
        }
        return new EnumDecl(from(start), name, literals);
    }

    private static boolean startsElement(Token t) {
        return switch (t.kind()) {
            case WORD -> true;
            case INT -> true;
            case KEYWORD -> Set.of("abstract", "initial", "final", "finalref", "finaltarget", "xor", "or", "mux", "opt",
                    "assert").contains(t.text());
            case SYMBOL -> Set.of("`", "[", "<<").contains(t.text());
            default -> false;
        };
    }

    private Element element() {
        Token t = peek();
        if (is(t, "[")) {
            return constraint();
        }
        if (is(t, "assert")) {
            pos++;
            expect("[");
            List<Exp> exps = expList("]");
            expect("]");
            return new Assertion(from(t), exps);
        }
        if (is(t, "<<")) {
            return goal();
        }
        if (is(t, "`")) {
            pos++;
            Name name = name();
            Optional<Card> card = card();
            Optional<Elements> elements = elements();
            return new ClaferUse(from(t), name, card, elements);
        }
        return clafer();
    }

    private Constraint constraint() {
        Token start = expect("[");
        List<Exp> exps = expList("]");
        expect("]");
        return new Constraint(from(start), exps);
    }

    private Goal goal() {
        Token start = expect("<<");
        Token k = peek();
        GoalKind kind;
        if (is(k, "min")) {
            kind = GoalKind.MinDeprecated;
        } else if (is(k, "max")) {
            kind = GoalKind.MaxDeprecated;
        } else if (is(k, "minimize")) {
            kind = GoalKind.Minimize;
        } else if (is(k, "maximize")) {
            kind = GoalKind.Maximize;
        } else {
            throw error(k, "Expected 'minimize' or 'maximize' after '<<' but found " + show(k));
        }
        pos++;
        List<Exp> exps = expList(">>");
        expect(">>");
        return new Goal(from(start), kind, exps);
    }

    private Clafer clafer() {
        Token start = peek();
        boolean isAbstract = accept("abstract");
        List<TempModifier> modifiers = new ArrayList<>();
        while (peek().kind() == TokenKind.KEYWORD && Modifiers.containsKey(peek().text())) {
            Token m = take();
            modifiers.add(new TempModifier(m.span(), Modifiers.get(m.text())));
        }
        Optional<GCard> groupCard = Optional.empty();
        if (peek().kind() == TokenKind.KEYWORD && GroupKeywords.contains(peek().text())) {
            Token g = take();
            groupCard = Optional.of(new GroupKeyword(g.span(), g.text()));
        } else if (peek().kind() == TokenKind.INT) {
            groupCard = Optional.of(ncard());
        }
        Ident name = ident("the name of a clafer");
        Optional<Super> superClafer = Optional.empty();
        if (at(":")) {
            Token s = take();
            superClafer = Optional.of(new Super(from(s), exp26()));
        }
        Optional<Reference> reference = Optional.empty();
        if (at("->") || at("->>")) {
            Token r = take();
            Exp target = exp23();
            reference = Optional.of(new Reference(from(r), r.text().equals("->>"), target));
        }
        Optional<Card> card = card();
        Optional<Init> init = Optional.empty();
        if (at("=") || at(":=")) {
            Token i = take();
            InitHow how = InitHow.Constant;
            if (i.text().equals(":=")) {
                how = accept("each") ? InitHow.Each : accept("together") ? InitHow.Together : InitHow.Default;
            }
            Exp value = exp();
            init = Optional.of(new Init(from(i), how, value));
        }
        Optional<ClaferTransition> transition = Optional.empty();
        if (startsArrow()) {
            Token t = peek();
            TransArrow arrow = arrow();
            Exp to = exp();
            transition = Optional.of(new ClaferTransition(from(t), arrow, to));
        }
        Optional<Elements> elements = elements();
        return new Clafer(from(start), isAbstract, modifiers, groupCard, name, superClafer, reference, card, init,
                transition, elements);
    }

    private NCard ncard() {
        Token low = take();
        expect("..");
        Token high = peek();
        if (is(high, "*")) {
            pos++;
            return new NCard(from(low), low.text(), Optional.empty());
        }
        if (high.kind() != TokenKind.INT) {
            throw error(high, "Expected a number or '*' after '..' but found " + show(high));
        }
        pos++;
        return new NCard(from(low), low.text(), Optional.of(high.text()));
    }

    private Optional<Card> card() {
        Token t = peek();
        if (is(t, "?") || is(t, "+") || is(t, "*")) {
            pos++;
            return Optional.of(new CardSymbol(t.span(), t.text()));
        }
        if (t.kind() == TokenKind.INT) {
            if (is(peek(1), "..")) {
                return Optional.of(ncard());
            }
            pos++;
            return Optional.of(new CardNum(t.span(), t.text()));
        }
        return Optional.empty();
    }

    private Optional<Elements> elements() {
        if (!isOpen(peek())) {
            return Optional.empty();
        }
        Token start = take();
        List<Element> elements = new ArrayList<>();
        while (!isClose(peek())) {
            if (peek().kind() == TokenKind.EOF) {
                throw error(peek(), "Expected '}' but found " + show(peek()));
            }
            if (peek().kind() == TokenKind.SEPARATOR) {
                pos++;
                continue;
            }
            int before = pos;
            try {
                if (!startsElement(peek())) {
                    throw error(peek(), "Expected a clafer, a constraint, an objective or an assertion but found "
                            + show(peek()));
                }
                elements.add(element());
            } catch (ParseError e) {
                recover(e, before);
            }
        }
        take();
        sameLineClafers(elements, diagnostics);
        return Optional.of(new Elements(from(start), elements));
    }

    /**
     * Elements have no separator, so {@code b : B A 3} would be two sibling
     * clafers, {@code b : B} and {@code A 3}: a clafer must start on a new
     * line after its previous sibling clafer, as the compiler requires.
     */
    private static void sameLineClafers(List<Element> elements, List<Diagnostic> diagnostics) {
        Element previous = null;
        for (Element e : elements) {
            String name = switch (e) {
                case Clafer c -> c.name().text();
                case ClaferUse u -> "`" + String.join("\\", u.name().path().stream().map(Ident::text).toList());
                default -> null;
            };
            if (name == null) {
                continue;
            }
            if (previous != null && previous.span().line() == e.span().line()) {
                diagnostics.add(new Diagnostic(SourceSpan.at(e.span().line(), e.span().column()),
                        "clafer " + name + " must start on a new line"));
            }
            previous = e;
        }
    }

    private Name name() {
        Token start = peek();
        List<Ident> path = new ArrayList<>();
        path.add(ident("a name"));
        while (accept("\\")) {
            path.add(ident("a name"));
        }
        return new Name(from(start), path);
    }

    // ------------------------------------------------------------------
    // Expressions
    // ------------------------------------------------------------------
    private static boolean startsExp(Token t) {
        return switch (t.kind()) {
            case WORD, INT, DECIMAL, DOUBLE, STRING -> true;
            case KEYWORD -> ExpStartWords.contains(t.text());
            case SYMBOL -> Set.of("(", "!", "-", "#").contains(t.text());
            default -> false;
        };
    }

    /**
     * Expressions up to the closing symbol, with no separator between them.
     */
    private List<Exp> expList(String close) {
        List<Exp> exps = new ArrayList<>();
        while (!at(close)) {
            if (!startsExp(peek())) {
                throw error(peek(), "Expected an expression or '" + close + "' but found " + show(peek()));
            }
            exps.add(exp());
        }
        return exps;
    }

    private boolean startsArrow() {
        return at("-->") || at("-->>") || at("-[");
    }

    private TransArrow arrow() {
        Token start = take();
        return switch (start.text()) {
            case "-->" -> new TransArrow(start.span(), false, Optional.empty());
            case "-->>" -> new TransArrow(start.span(), true, Optional.empty());
            default -> {
                Exp guard = exp1();
                Token close = peek();
                if (!is(close, "]->") && !is(close, "]->>")) {
                    throw error(close, "Expected ']->' or ']->>' after the guard but found " + show(close));
                }
                pos++;
                yield new TransArrow(from(start), close.text().equals("]->>"), Optional.of(guard));
            }
        };
    }

    /**
     * {@code Exp ::= Exp1 TransArrow Exp | Exp1}.
     */
    private Exp exp() {
        Exp from = exp1();
        if (startsArrow()) {
            TransArrow arrow = arrow();
            Exp to = exp();
            return new TransitionExp(join(from, to), from, arrow, to);
        }
        return from;
    }

    /**
     * The quantifiers with a declaration, {@code if}, {@code let}.
     */
    private Exp exp1() {
        Token t = peek();
        boolean all = is(t, "all");
        if (all || (t.kind() == TokenKind.KEYWORD && Quants.containsKey(t.text()) && startsDecl(peek(1), peek(2)))) {
            pos++;
            boolean disj = accept("disj");
            Decl decl = decl();
            expect("|");
            Exp body = exp1();
            return new Quantified(from(t), all ? Quant.All : Quants.get(t.text()), disj, decl, body);
        }
        if (is(t, "if")) {
            pos++;
            Exp condition = exp1();
            expect("then");
            Exp then = exp1();
            expect("else");
            Exp otherwise = exp1();
            return new IfThenElse(from(t), condition, then, otherwise);
        }
        if (is(t, "let")) {
            pos++;
            Ident local = ident("the name of a local variable");
            expect("=");
            Exp value = exp16();
            expect("in");
            Exp body = exp1();
            return new Let(from(t), local, value, body);
        }
        return exp2();
    }

    /**
     * A declaration follows a quantifier when {@code disj}, or a name and
     * {@code ;} or {@code :}, follow it: one token more than Happy looks at,
     * since Happy decides on the name.
     */
    private static boolean startsDecl(Token next, Token afterNext) {
        return is(next, "disj") || (next.kind() == TokenKind.WORD && (is(afterNext, ":") || is(afterNext, ";")));
    }

    private Decl decl() {
        Token start = peek();
        List<Ident> locals = new ArrayList<>();
        locals.add(ident("the name of a local variable"));
        while (accept(";")) {
            locals.add(ident("the name of a local variable"));
        }
        expect(":");
        Exp set = exp21();
        return new Decl(from(start), locals, set);
    }

    /**
     * The behavioral patterns and the anchors.
     */
    private Exp exp2() {
        Token t = peek();
        if (t.kind() == TokenKind.KEYWORD && PrefixPatterns.containsKey(t.text())) {
            pos++;
            Exp e = exp3();
            Optional<PatternScope> scope = patternScope();
            return new Pattern(from(t), PrefixPatterns.get(t.text()), List.of(e), scope);
        }
        if (is(t, "initially") || is(t, "finally")) {
            pos++;
            Exp e = exp3();
            return new Anchor(from(t), t.text().equals("initially"), e);
        }
        Exp left = exp3();
        if (at("must")) {
            pos++;
            Token k = peek();
            PatternKind kind;
            if (is(k, "precede")) {
                kind = PatternKind.Precede;
            } else if (is(k, "follow")) {
                kind = PatternKind.Follow;
            } else {
                throw error(k, "Expected 'precede' or 'follow' after 'must' but found " + show(k));
            }
            pos++;
            Exp right = exp3();
            Optional<PatternScope> scope = patternScope();
            return new Pattern(from(left), kind, List.of(left, right), scope);
        }
        return left;
    }

    private SourceSpan from(Node start) {
        return new SourceSpan(start.span().line(), start.span().column(), last().span().endLine(),
                last().span().endColumn());
    }

    private Optional<PatternScope> patternScope() {
        Token t = peek();
        if (is(t, "before")) {
            pos++;
            return Optional.of(new PatternScope(from(t), ScopeKind.Before, List.of(exp11())));
        }
        if (is(t, "between")) {
            pos++;
            Exp a = exp11();
            expect("and");
            Exp b = exp11();
            return Optional.of(new PatternScope(from(t), ScopeKind.BetweenAnd, List.of(a, b)));
        }
        if (is(t, "after")) {
            pos++;
            Exp a = exp11();
            if (accept("until")) {
                Exp b = exp11();
                return Optional.of(new PatternScope(from(t), ScopeKind.AfterUntil, List.of(a, b)));
            }
            return Optional.of(new PatternScope(from(t), ScopeKind.After, List.of(a)));
        }
        return Optional.empty();
    }

    private Exp exp3() {
        Exp left = exp4();
        while (at("<=>")) {
            pos++;
            Exp right = exp4();
            left = new Binary(join(left, right), BinaryOp.Iff, left, right);
        }
        return left;
    }

    private Exp exp4() {
        Exp left = exp5();
        while (at("=>")) {
            pos++;
            Exp right = exp5();
            left = new Binary(join(left, right), BinaryOp.Implies, left, right);
        }
        return left;
    }

    private Exp exp5() {
        Exp left = exp6();
        while (at("||")) {
            pos++;
            Exp right = exp6();
            left = new Binary(join(left, right), BinaryOp.Or, left, right);
        }
        return left;
    }

    private Exp exp6() {
        Exp left = exp7();
        while (at("xor")) {
            pos++;
            Exp right = exp7();
            left = new Binary(join(left, right), BinaryOp.Xor, left, right);
        }
        return left;
    }

    private Exp exp7() {
        Exp left = exp8();
        while (at("&&")) {
            pos++;
            Exp right = exp8();
            left = new Binary(join(left, right), BinaryOp.And, left, right);
        }
        return left;
    }

    private Exp exp8() {
        Exp left = exp9();
        while (true) {
            BinaryOp op = at("U") ? BinaryOp.LtlU : at("until") ? BinaryOp.Until : at("since") ? BinaryOp.Since
                    : at("triggered") ? BinaryOp.Triggered : null;
            if (op == null) {
                return left;
            }
            pos++;
            Exp right = exp9();
            left = new Binary(join(left, right), op, left, right);
        }
    }

    private Exp exp9() {
        Exp left = exp10();
        while (at("W") || at("weakuntil")) {
            BinaryOp op = at("W") ? BinaryOp.LtlW : BinaryOp.WeakUntil;
            pos++;
            Exp right = exp10();
            left = new Binary(join(left, right), op, left, right);
        }
        return left;
    }

    private Exp exp10() {
        Token t = peek();
        if (t.kind() == TokenKind.KEYWORD && TemporalPrefix.containsKey(t.text())) {
            pos++;
            Exp e = exp10();
            return new Unary(from(t), TemporalPrefix.get(t.text()), e);
        }
        return exp11();
    }

    private Exp exp11() {
        Token t = peek();
        if (is(t, "!")) {
            pos++;
            Exp e = exp11();
            return new Unary(from(t), UnaryOp.Neg, e);
        }
        return exp15();
    }

    private Exp exp15() {
        Exp left = exp16();
        while (true) {
            Token t = peek();
            BinaryOp op;
            if (is(t, "not")) {
                // a not ... is a not in: Happy shifts the not
                pos++;
                expect("in");
                op = BinaryOp.NotIn;
            } else if ((t.kind() == TokenKind.SYMBOL || t.kind() == TokenKind.KEYWORD)
                    && Comparisons.containsKey(t.text())) {
                pos++;
                op = Comparisons.get(t.text());
            } else {
                return left;
            }
            Exp right = exp16();
            left = new Binary(join(left, right), op, left, right);
        }
    }

    private Exp exp16() {
        Token t = peek();
        if (t.kind() == TokenKind.KEYWORD && Quants.containsKey(t.text())) {
            pos++;
            Exp e = exp20();
            return new QuantExp(from(t), Quants.get(t.text()), e);
        }
        return exp17();
    }

    private Exp exp17() {
        Exp left = exp18();
        while (at("+") || at("-")) {
            BinaryOp op = at("+") ? BinaryOp.Add : BinaryOp.Sub;
            pos++;
            Exp right = exp18();
            left = new Binary(join(left, right), op, left, right);
        }
        return left;
    }

    private Exp exp18() {
        Exp left = exp19();
        while (at("*") || at("/") || at("%")) {
            BinaryOp op = at("*") ? BinaryOp.Mul : at("/") ? BinaryOp.Div : BinaryOp.Rem;
            pos++;
            Exp right = exp19();
            left = new Binary(join(left, right), op, left, right);
        }
        return left;
    }

    private Exp exp19() {
        Token t = peek();
        if (is(t, "max") || is(t, "min")) {
            pos++;
            Exp e = exp20();
            return new Unary(from(t), t.text().equals("max") ? UnaryOp.GMax : UnaryOp.GMin, e);
        }
        return exp20();
    }

    private Exp exp20() {
        Token t = peek();
        UnaryOp op = is(t, "sum") ? UnaryOp.Sum : is(t, "product") ? UnaryOp.Product : is(t, "#") ? UnaryOp.Card
                : is(t, "-") ? UnaryOp.Minus : null;
        if (op != null) {
            pos++;
            Exp e = exp21();
            return new Unary(from(t), op, e);
        }
        return exp21();
    }

    private Exp exp21() {
        Exp left = exp22();
        while (at("<:")) {
            pos++;
            Exp right = exp22();
            left = new Binary(join(left, right), BinaryOp.Domain, left, right);
        }
        return left;
    }

    private Exp exp22() {
        Exp left = exp23();
        while (at(":>")) {
            pos++;
            Exp right = exp23();
            left = new Binary(join(left, right), BinaryOp.Range, left, right);
        }
        return left;
    }

    private Exp exp23() {
        Exp left = exp24();
        while (at("++") || at(",")) {
            BinaryOp op = at("++") ? BinaryOp.Union : BinaryOp.UnionCom;
            pos++;
            Exp right = exp24();
            left = new Binary(join(left, right), op, left, right);
        }
        return left;
    }

    private Exp exp24() {
        Exp left = exp25();
        while (at("--")) {
            pos++;
            Exp right = exp25();
            left = new Binary(join(left, right), BinaryOp.Difference, left, right);
        }
        return left;
    }

    private Exp exp25() {
        Exp left = exp26();
        while (at("**")) {
            pos++;
            Exp right = exp26();
            left = new Binary(join(left, right), BinaryOp.Intersection, left, right);
        }
        return left;
    }

    private Exp exp26() {
        Exp left = exp27();
        while (at(".") || at("&")) {
            BinaryOp op = at(".") ? BinaryOp.Join : BinaryOp.IntersectionDeprecated;
            pos++;
            Exp right = exp27();
            left = new Binary(join(left, right), op, left, right);
        }
        return left;
    }

    private Exp exp27() {
        Token t = peek();
        switch (t.kind()) {
            case WORD -> {
                Name name = name();
                return new ClaferId(name.span(), name);
            }
            case INT -> {
                pos++;
                return new Literal(t.span(), LiteralKind.Int, t.text());
            }
            case DOUBLE -> {
                pos++;
                return new Literal(t.span(), LiteralKind.Double, t.text());
            }
            case DECIMAL -> {
                pos++;
                return new Literal(t.span(), LiteralKind.Real, t.text());
            }
            case STRING -> {
                pos++;
                return new Literal(t.span(), LiteralKind.Str, t.text());
            }
            default -> {
                if (is(t, "(")) {
                    pos++;
                    Exp e = exp();
                    expect(")");
                    return e;
                }
                throw error(t, "Expected an expression but found " + show(t));
            }
        }
    }
}
